<script setup lang="ts">
import { computed,onBeforeUnmount,reactive,ref,watch } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import { Download,Plus,RefreshCw,Search } from 'lucide-vue-next';
import { ElMessage,ElMessageBox } from 'element-plus';
import { api } from '../api';
import { useSessionStore } from '../stores/session';
import { useResponsiveDrawer } from '../province-monitoring';
import { exportAdmission } from '../admission';
import { useSafetyList } from '../useSafetyList';
import { fail,permission,sf,sl,statusTone } from '../safety-workspace';
import QueryPanel from '../components/QueryPanel.vue';import QueryField from '../components/QueryField.vue';
import SafetyMaterials from '../components/SafetyMaterials.vue';import SafetyTaskDrawer from '../components/SafetyTaskDrawer.vue';
import '../subject-management.css';import '../safety-workspace.css';
const session=useSessionStore(),route=useRoute(),router=useRouter(),width=useResponsiveDrawer(650),enterprise=computed(()=>session.user?.portal==='ENTERPRISE'),canCreate=computed(()=>!enterprise.value&&permission(session.user,'safety:violation:write'));
const {filters,rows,total,page,loading,error,search,reset,load,getFilters}=useSafetyList('/governance/inspections',{q:'',status:'',type:''});
const table=ref<any>();const selected=ref<any[]>([]),drawer=ref(false),detailId=ref(''),detail=ref<any>(),detailLoading=ref(false),detailError=ref(''),tab=ref('record'),editor=ref(false),resultDialog=ref(false),saving=ref(false),uploading=ref(false),editorError=ref(''),resultError=ref(''),options=ref<any>({enterprises:[]}),optionsError=ref(''),resultMaterials=ref<any[]>([]),exporting=ref(false),taskOpen=ref(false),taskId=ref('');
const form=reactive({title:'',enterpriseId:'',inspectionType:'ROUTINE',inspectorName:'',scheduledAt:''}),resultForm=reactive({result:'',issues:[] as any[]});let generation=0,controller:AbortController|undefined,editorInitial='',resultInitial='';
async function loadOptions(){optionsError.value='';try{options.value=await api('/safety/workspace/options')}catch(e){optionsError.value=fail(e)}}
async function loadDetail(){const g=++generation;controller?.abort();controller=new AbortController();detailLoading.value=true;detailError.value='';detail.value=undefined;try{const data=await api<any>(`/governance/inspections/${detailId.value}`,{signal:controller.signal});if(g===generation)detail.value=data}catch(e){if(g===generation&&!controller.signal.aborted)detailError.value=fail(e)}finally{if(g===generation)detailLoading.value=false}}
function open(row:any){detailId.value=row.id;tab.value='record';drawer.value=true;void router.replace({path:route.path,query:{...route.query,inspectionId:row.id}});void loadDetail()}
function create(){Object.assign(form,{title:'',enterpriseId:'',inspectionType:'ROUTINE',inspectorName:session.user?.displayName??'',scheduledAt:''});editorInitial=JSON.stringify(form);editorError.value='';editor.value=true}
async function closeEditor(which:'plan'|'result'){if(saving.value||uploading.value)return;const current=which==='plan'?JSON.stringify(form):JSON.stringify({...resultForm,materialIds:resultMaterials.value.map(m=>m.id)}),initial=which==='plan'?editorInitial:resultInitial;if(current!==initial){try{await ElMessageBox.confirm('尚有未提交内容，是否放弃本次填写？','放弃未提交内容',{confirmButtonText:'放弃改动',cancelButtonText:'继续填写'})}catch{return}}if(which==='plan')editor.value=false;else resultDialog.value=false}
async function savePlan(){if(!form.title.trim()||!form.enterpriseId||!form.inspectorName.trim()||!form.scheduledAt)return ElMessage.warning('请完整填写检查计划');saving.value=true;editorError.value='';try{const data=await api<any>('/governance/inspections',{method:'POST',body:JSON.stringify({...form,scheduledAt:new Date(form.scheduledAt).toISOString()})});editor.value=false;ElMessage.success('检查计划已创建');await load();open(data)}catch(e){editorError.value=fail(e)}finally{saving.value=false}}
function issue(){return {title:'',requirement:'',responsibleName:'',dueAt:''}}
function record(){Object.assign(resultForm,{result:detail.value?.result??'',issues:Array.from({length:detail.value?.legacyIssueCount??0},issue)});resultMaterials.value=[...(detail.value?.materials??[])];resultInitial=JSON.stringify({...resultForm,materialIds:resultMaterials.value.map(m=>m.id)});resultError.value='';resultDialog.value=true}
async function saveResult(){if(!resultForm.result.trim())return ElMessage.warning('请填写检查结论');if(resultForm.issues.some(i=>!i.title.trim()||!i.requirement.trim()||!i.responsibleName.trim()||!i.dueAt))return ElMessage.warning('请完整填写每项问题、整改要求、负责人和期限');saving.value=true;resultError.value='';try{detail.value=await api(`/governance/inspections/${detailId.value}/result`,{method:'POST',body:JSON.stringify({result:resultForm.result,version:detail.value.version,issues:resultForm.issues.map(i=>({...i,dueAt:new Date(i.dueAt).toISOString()})),materialIds:resultMaterials.value.map(m=>m.id)})});resultDialog.value=false;tab.value=detail.value.issues.length?'issues':'record';ElMessage.success(detail.value.issues.length?'检查结果已登记，已逐项下达整改任务':'检查结果已登记');await load()}catch(e){resultError.value=fail(e)}finally{saving.value=false}}
function follow(i:any){if(!i.task)return;taskId.value=i.task.id;taskOpen.value=true}
async function updated(){await Promise.all([load(),loadDetail()])}
async function closeInspection(){let content='';try{content=(await ElMessageBox.prompt('填写检查办结意见，确认没有未完成的整改问题。','办结检查',{inputType:'textarea',inputValidator:(v:string)=>v?.trim()?true:'请填写办结意见'})).value}catch{return}saving.value=true;try{await api(`/governance/inspections/${detailId.value}/actions`,{method:'POST',body:JSON.stringify({action:'CLOSE',content})});ElMessage.success('检查已办结');await updated()}catch(e){ElMessage.error(fail(e))}finally{saving.value=false}}
async function exportRows(){exporting.value=true;try{await exportAdmission('/governance/inspections',getFilters(),[['检查名称',r=>r.title],['检查编号',r=>r.businessNo],['被检查企业',r=>r.enterprise?.name],['检查类型',r=>sl(r.inspectionType)],['检查人员',r=>r.inspectorName],['计划时间',r=>sf(r.scheduledAt)],['检查状态',r=>sl(r.status)],['问题数',r=>r.issueCount]],'监督检查',selected.value)}catch(e){ElMessage.error(fail(e))}finally{exporting.value=false}}
watch(()=>route.query.inspectionId,id=>{if(id&&id!==detailId.value){detailId.value=String(id);drawer.value=true;tab.value='record';void loadDetail()}},{immediate:true});watch(drawer,v=>{if(!v){generation++;controller?.abort();void router.replace({path:route.path,query:{...route.query,inspectionId:undefined}})}});watch(rows,()=>{selected.value=[];table.value?.clearSelection()});void loadOptions();onBeforeUnmount(()=>{generation++;controller?.abort()});
</script>
<template><section class="city-subject-page safety-workspace-page" :class="{'safety-drawer-open':drawer||taskOpen}"><h1 class="sr-only">监督检查</h1><QueryPanel class="subject-query" :loading="loading" @search="search()" @reset="reset"><QueryField label="关键词" keyword><el-input v-model="filters.q" aria-label="搜索监督检查" :prefix-icon="Search" clearable placeholder="搜索检查名称、编号或企业"/></QueryField><QueryField label="检查类型"><el-select v-model="filters.type" aria-label="检查类型" clearable placeholder="全部类型"><el-option v-for="type in ['ROUTINE','SPECIAL','RANDOM']" :key="type" :label="sl(type)" :value="type"/></el-select></QueryField><QueryField label="检查状态"><el-select v-model="filters.status" aria-label="检查状态" clearable placeholder="全部状态"><el-option v-for="status in ['PLANNED','RECTIFYING','PENDING_REVIEW','COMPLETED']" :key="status" :label="status==='PENDING_REVIEW'?'待复查':sl(status)" :value="status"/></el-select></QueryField></QueryPanel><section class="safety-surface"><header class="safety-header"><h2>监督检查<span class="subject-count">{{total}}</span></h2><div><el-button :icon="RefreshCw" :loading="loading" @click="load">刷新</el-button><el-button :icon="Download" :loading="exporting" @click="exportRows">导出</el-button><el-button v-if="canCreate" :icon="Plus" type="primary" @click="create">新建检查</el-button></div></header><div class="safety-tabs" style="margin-bottom:12px"><button v-for="status in ['','PLANNED','RECTIFYING','PENDING_REVIEW','COMPLETED']" :key="status" type="button" :aria-pressed="filters.status===status" @click="filters.status=status;search()">{{!status?'全部检查':status==='PENDING_REVIEW'?'待复查':sl(status)}}</button></div><div v-if="selected.length" class="subject-bulk"><span>已选{{selected.length}}项</span><el-button link type="primary" :loading="exporting" @click="exportRows">导出所选</el-button><el-button link @click="table?.clearSelection()">取消选择</el-button></div><div v-if="error" class="safety-error"><strong>检查列表暂时无法读取</strong><span>{{error}}</span><el-button @click="load">重试</el-button></div><div v-else class="safety-table-host"><el-table ref="table" v-loading="loading" :data="rows" height="100%" class="subject-table" row-key="id" empty-text="暂无符合条件的检查记录" :row-class-name="({row}:any)=>drawer&&row.id===detailId?'safety-row-selected':''" @selection-change="selected=$event"><el-table-column type="selection" width="44"/><el-table-column label="检查名称 / 编号" min-width="260"><template #default="{row}"><button type="button" class="subject-identity" @click="open(row)"><strong>{{row.title}}</strong><span>{{row.businessNo}}</span></button></template></el-table-column><el-table-column v-if="!enterprise" label="被检查企业" min-width="185"><template #default="{row}">{{row.enterprise?.name}}</template></el-table-column><el-table-column label="类型" width="95"><template #default="{row}">{{sl(row.inspectionType)}}</template></el-table-column><el-table-column label="计划时间" width="145"><template #default="{row}">{{sf(row.scheduledAt)}}</template></el-table-column><el-table-column label="状态 / 问题" width="115"><template #default="{row}"><el-tag size="small" :type="statusTone(row.status)">{{row.status==='PENDING_REVIEW'?'待复查':sl(row.status)}}</el-tag><span class="safety-deadline">{{row.issueCount}}项问题</span></template></el-table-column><el-table-column label="操作" width="90" fixed="right"><template #default="{row}"><el-button link type="primary" @click="open(row)">详情</el-button></template></el-table-column></el-table></div><footer class="subject-footer"><span>共{{total}}条</span><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="prev,pager,next" @current-change="search(false)"/></footer></section>
<el-drawer v-model="drawer" title="检查详情" :size="width" class="safety-detail-drawer" :z-index="1700" :modal="false" destroy-on-close><div v-if="detailError" class="safety-error"><strong>检查详情暂时无法读取</strong><span>{{detailError}}</span><el-button @click="loadDetail">重试</el-button></div><div v-else v-loading="detailLoading" style="min-height:180px"><template v-if="detail"><div class="safety-identity"><h3>{{detail.title}}</h3><div><span class="safety-muted">{{detail.businessNo}}</span><el-tag size="small" type="info">{{sl(detail.inspectionType)}}</el-tag><el-tag size="small" :type="statusTone(detail.status)">{{detail.status==='PENDING_REVIEW'?'待复查':sl(detail.status)}}</el-tag></div></div><div class="safety-tabs"><button v-for="t in [['record','检查记录'],['issues',`问题清单（${detail.issueCount}）`],['review','整改与复查']]" :key="t[0]" type="button" :aria-pressed="tab===t[0]" @click="tab=t[0]!">{{t[1]}}</button></div><template v-if="tab==='record'"><dl class="safety-facts"><div class="wide"><dt>被检查企业</dt><dd>{{detail.enterprise?.name}}</dd></div><div><dt>检查人员</dt><dd>{{detail.inspectorName}}</dd></div><div><dt>计划时间</dt><dd>{{sf(detail.scheduledAt)}}</dd></div><div><dt>实际完成时间</dt><dd>{{sf(detail.completedAt)}}</dd></div><div><dt>关联整改任务</dt><dd>{{detail.issues.filter((i:any)=>i.task).length}}项</dd></div></dl><section class="safety-section"><h4>检查结论</h4><p>{{detail.result||'尚未登记检查结果'}}</p></section></template><template v-if="tab==='record'||tab==='issues'"><section class="safety-section"><h4>问题清单</h4><div v-if="detail.legacyIssueCount" class="safety-inline-error">历史记录已登记{{detail.legacyIssueCount}}项问题，尚未形成逐项清单。<el-button v-if="canCreate&&detail.status!=='CLOSED'" link type="primary" @click="record">补充问题清单</el-button></div><div v-for="i in detail.issues" :key="i.id" class="safety-issue"><header><b>{{String(i.sequence).padStart(2,'0')}}</b><strong>{{i.title}}</strong><el-tag size="small" :type="statusTone(i.task?.status??'WAITING_RESPONSE')">{{i.task?.status==='PENDING_REVIEW'?'已整改待复查':i.task?.status==='CLOSED'?'复查通过':i.task?.status==='IN_PROGRESS'?'整改中':sl(i.task?.status)}}</el-tag></header><p class="safety-muted">{{i.requirement}}</p><dl class="safety-facts"><div><dt>责任人</dt><dd>{{i.responsibleName}}</dd></div><div><dt>整改期限</dt><dd>{{sf(i.task?.dueAt??i.dueAt)}}</dd></div></dl><p v-if="i.task?.feedback">{{i.task.feedback}}</p><SafetyMaterials :model-value="i.task?.materials??[]"/><el-button v-if="i.task&&permission(session.user,'safety:emergency:read')" link type="primary" @click="follow(i)">{{i.task.status==='PENDING_REVIEW'&&!enterprise?'登记复查':'查看整改任务'}}</el-button><p v-if="i.task?.reviewComment" class="safety-muted">复查意见：{{i.task.reviewComment}}</p></div><el-empty v-if="!detail.issues.length&&!detail.legacyIssueCount" :description="detail.status==='PLANNED'?'登记检查结果后展示发现的问题':'本次检查未发现问题'" :image-size="50"/></section><section class="safety-section"><h4>检查材料</h4><SafetyMaterials :model-value="detail.materials"/></section></template><section v-if="tab==='review'" class="safety-section"><h4>检查及复查记录</h4><ul class="safety-log"><li v-for="(h,i) in detail.history" :key="i"><strong>{{sl(h.action)}} · {{h.actorName}}</strong><small>{{sf(h.createdAt)}}</small><p>{{h.content}}</p></li><template v-for="issue in detail.issues" :key="issue.id"><li v-for="(h,i) in issue.task?.history??[]" :key="`${issue.id}-${i}`"><strong>{{issue.title}} · {{sl(h.action)}}</strong><small>{{sf(h.createdAt)}} · {{h.actorName}}</small><p>{{h.content}}</p></li></template></ul><el-empty v-if="!detail.history.length&&!detail.issues.length" description="暂无新增记录" :image-size="50"/></section></template></div><template #footer><el-button @click="drawer=false">关闭</el-button><template v-if="detail"><el-button v-if="detail.status==='PLANNED'&&canCreate" type="primary" @click="record">登记检查结果</el-button><el-button v-else-if="detail.issues.length" type="primary" @click="tab='issues'">查看整改任务</el-button><el-button v-else-if="!enterprise&&detail.status==='COMPLETED'&&permission(session.user,'safety:violation:review')" type="primary" :loading="saving" @click="closeInspection">办结检查</el-button></template></template></el-drawer>
<SafetyTaskDrawer v-model="taskOpen" :id="taskId" task-type="RECTIFICATION" @changed="updated"/>
<el-dialog v-model="editor" title="新建检查计划" width="min(680px,95vw)" class="safety-editor" :close-on-click-modal="false" :before-close="()=>closeEditor('plan')"><div v-if="editorError||optionsError" class="safety-inline-error" role="alert">{{editorError||optionsError}}<el-button v-if="optionsError" link @click="loadOptions">重新读取企业</el-button></div><el-form label-position="top" class="safety-form-grid"><el-form-item label="检查名称" class="wide" required><el-input v-model="form.title" aria-label="检查名称" maxlength="150"/></el-form-item><el-form-item label="被检查企业" required><el-select v-model="form.enterpriseId" filterable aria-label="被检查企业"><el-option v-for="e in options.enterprises" :key="e.id" :label="e.name" :value="e.id"/></el-select></el-form-item><el-form-item label="检查类型" required><el-select v-model="form.inspectionType" aria-label="计划检查类型"><el-option v-for="t in ['ROUTINE','SPECIAL','RANDOM']" :key="t" :label="sl(t)" :value="t"/></el-select></el-form-item><el-form-item label="检查人员" required><el-input v-model="form.inspectorName" aria-label="检查人员" maxlength="150"/></el-form-item><el-form-item label="计划时间" required><el-date-picker v-model="form.scheduledAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" aria-label="检查计划时间"/></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="closeEditor('plan')">取消</el-button><el-button type="primary" :loading="saving" @click="savePlan">创建计划</el-button></template></el-dialog>
<el-dialog v-model="resultDialog" title="登记检查结果" width="min(800px,95vw)" class="safety-editor" :close-on-click-modal="false" :before-close="()=>closeEditor('result')"><div v-if="resultError" class="safety-inline-error" role="alert">{{resultError}}</div><el-form label-position="top"><el-form-item label="检查结论" required><el-input v-model="resultForm.result" type="textarea" :rows="3" maxlength="5000" aria-label="检查结论"/></el-form-item><section class="safety-section"><h4>发现问题 {{resultForm.issues.length}}项</h4><div v-for="(i,index) in resultForm.issues" :key="index" class="safety-issue"><header><b>{{String(index+1).padStart(2,'0')}}</b><strong>问题{{index+1}}</strong><el-button link type="danger" :disabled="saving" @click="resultForm.issues.splice(index,1)">移除</el-button></header><el-form-item label="问题名称" required><el-input v-model="i.title" :aria-label="`问题${index+1}名称`" maxlength="150"/></el-form-item><el-form-item label="整改要求" required><el-input v-model="i.requirement" type="textarea" :rows="2" :aria-label="`问题${index+1}整改要求`" maxlength="5000"/></el-form-item><div class="safety-form-grid"><el-form-item label="责任人" required><el-input v-model="i.responsibleName" :aria-label="`问题${index+1}责任人`" maxlength="80"/></el-form-item><el-form-item label="整改期限" required><el-date-picker v-model="i.dueAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ssZ" :aria-label="`问题${index+1}整改期限`"/></el-form-item></div></div><el-button :icon="Plus" :disabled="resultForm.issues.length>=50||saving" @click="resultForm.issues.push(issue())">添加问题</el-button><p v-if="!resultForm.issues.length" class="safety-muted">未发现问题时可直接登记检查结论。</p></section><el-form-item label="检查材料"><SafetyMaterials v-model="resultMaterials" :enterprise-id="detail?.enterpriseId" editable @busy="uploading=$event"/></el-form-item></el-form><template #footer><el-button :disabled="saving||uploading" @click="closeEditor('result')">取消</el-button><el-button type="primary" :loading="saving" :disabled="uploading" @click="saveResult">登记结果{{resultForm.issues.length?'并下达整改':''}}</el-button></template></el-dialog>
</section></template>
